import{_ as o,o as e,c as a,a2 as d}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"拡張機能の選び方","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/extensions.md","filePath":"ja/guides/extensions.md","lastUpdated":1792323081000}'),r={name:"ja/guides/extensions.md"};function s(l,t,h,i,n,c){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="拡張機能の選び方" tabindex="-1">拡張機能の選び方 <a class="header-anchor" href="#拡張機能の選び方" aria-label="Permalink to &quot;拡張機能の選び方&quot;">​</a></h1><p>Memoh には、Bot に能力を足す方法が 5 つあります。名前だけ見ると紛らわしいものの、並べてみればはっきりします——なので、そのまま並べました。</p><table tabindex="0"><thead><tr><th>拡張方式</th><th>それは何か</th><th>どこにあるか／どう発火するか</th><th>向いている用途</th></tr></thead><tbody><tr><td><a href="./skills.html">スキル</a></td><td>Bot の仕事のやり方を変える <code>SKILL.md</code> プロンプトモジュール</td><td>Bot ワークスペースの <code>/data/skills/</code> 配下。<strong>スキル</strong> タブで管理し、会話の中で呼び出す</td><td>本来なら毎回打ち直すことになる手順や仕事の進め方</td></tr><tr><td><a href="./hooks.html">Hooks</a></td><td><code>hooks.json</code> に書く、コマンドやツールを実行できるイベントルール</td><td><code>/data/.memoh/hooks.json</code> にあり、<strong>Hooks</strong> タブで編集。<code>PreToolUse</code> や <code>TurnEnd</code> のようなライフサイクルイベントで発火</td><td>決まったポイントでのチェックや付随アクション。チャットを一切経由しない</td></tr><tr><td><a href="./mcp.html">MCP</a></td><td>外部の MCP ツールサーバーへの接続</td><td>Bot ごとに <strong>MCP</strong> タブで設定し、Stdio または Remote で接続。発見されたツールは会話の中で使う</td><td>MCP server を自前で備えているツールをつなぐ</td></tr><tr><td><a href="./../self-hosted/connectors.html">コネクター</a></td><td>GitHub や Notion のようなサービスへの OAuth / API Key の紐付け</td><td>アプリのコンポーネントとして App と一緒にインストールされ、Bot の <strong>アプリ</strong> タブで認証・管理。サービスのツールが会話に現れる</td><td>ホスティングされたサービス上の自分のアカウントで Bot に作業させる</td></tr><tr><td><a href="./supermarket.html">マーケットプレイス</a></td><td>Memoh 内蔵のカタログ。パッケージ化されたアプリ——スキルとその依存関係・コネクター——をワンクリックでインストール</td><td>サイドバーから開く。インストールした内容は対象 Bot のワークスペースと <strong>アプリ</strong> タブに入る</td><td>部品を自分で組み立てずに、出来合いの能力をそのまま手に入れる</td></tr></tbody></table><p>能力がどの経路から入ってきても、最終的には同じ場所に合流します。コネクターと MCP のツールは会話の中でワークスペースツールと並んで現れ、インストールされたスキルは手書きのものと何も変わらない形で Bot の <strong>スキル</strong> タブに現れます。</p><h2 id="どれを使うべきか" tabindex="-1">どれを使うべきか <a class="header-anchor" href="#どれを使うべきか" aria-label="Permalink to &quot;どれを使うべきか&quot;">​</a></h2><ul><li>Bot の仕事のやり方を変えたい → <a href="./skills.html">スキル</a>。</li><li>決まったイベントの時点で自動的に何かをしたい → <a href="./hooks.html">Hooks</a>。</li><li>MCP server を持つツールをつなぎたい → <a href="./mcp.html">MCP</a>。</li><li>Bot に自分の GitHub/Notion アカウントを使わせたい → <a href="./../self-hosted/connectors.html">コネクター</a>。</li><li>出来合いの一式をワンクリックで入れたい → <a href="./supermarket.html">マーケットプレイス</a>。</li></ul><div class="tip custom-block"><p class="custom-block-title">重ねて使えます</p><p>この 5 つは排他的な選択肢ではありません。マーケットプレイスでインストールした 1 つのアプリがスキルとコネクターを同時に連れてくることもありますし、MCP 経由で入ってきたツールを Hook で見張ることもできます。Bot ごとに 1 種類だけ選ぶのではなく、上の問いに沿って選んでください。</p></div><h2 id="どこから始めるか" tabindex="-1">どこから始めるか <a class="header-anchor" href="#どこから始めるか" aria-label="Permalink to &quot;どこから始めるか&quot;">​</a></h2><p>どの方法にも 1 ページまるごとの解説があり、この表が圧縮してしまった詳細を展開しています:</p><ul><li><a href="./skills.html">スキル</a>——<code>SKILL.md</code> の書き方、スキルの状態、発見されたスキルの取り込み。</li><li><a href="./hooks.html">Hooks</a>——イベントカタログ、設定の構造、ルールのテスト方法。</li><li><a href="./mcp.html">MCP</a>——Stdio と Remote の接続、OAuth、ツールの発見。</li><li><a href="./../self-hosted/connectors.html">コネクター</a>——接続状態、再認証、ツールの名前空間。</li><li><a href="./supermarket.html">マーケットプレイス</a>——カタログの閲覧、Bot へのインストール。</li></ul><p>迷ったら、まずマーケットプレイスを覗いてみてください——出来合いのパッケージを 1 つインストールして、完成形がどんな姿なのかを先に見てから、自分のものを組み立てましょう。</p>',11)])])}const f=o(r,[["render",s]]);export{p as __pageData,f as default};
